# Comparison data for the viewer's "Compare" view (19 Nov 2026): product picks + what owners say, paints, placement check.
# Built from four research passes (see claude/MyFlat_research_products_2026-11-19.md). Prices = what the source page showed.
# Run: python3 scripts/compare_data.py models   -> models/compare.json
import json, os, sys
OUT = sys.argv[1] if len(sys.argv) > 1 else "."
def P(en, hi): return [en, hi]
def k(t, name, price, url, note=None):          # one pick: tier (b / m / p), name, price text, source link
    d = {"t": t, "n": name, "price": price, "url": url}
    if note: d["note"] = note
    return d

